package ru.neverland.townysieges;
import java.nio.file.*;import java.sql.*;import java.util.*;import java.util.concurrent.*;
/** Actual SQLite atomicity, legacy repair and duplicate/incorrect completion boundaries. */
public final class WarConclusionSmoke {
 static int checks;static void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}static <T>T done(CompletionStage<T> f)throws Exception{return f.toCompletableFuture().get(10,TimeUnit.SECONDS);}static void close(RaidStore s)throws Exception{s.close();done(s.stopped());}static void denied(CompletionStage<?> f)throws Exception{try{done(f);throw new AssertionError("unexpected completion");}catch(ExecutionException expected){checks++;}}
 static RaidStore.Raid raid(long now){return new RaidStore.Raid(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),now-1000,now-500,now+600000,now+86400000,"OPEN");}
 static WarCaptureStore.Capture capture(RaidStore.Raid r,int x){return new WarCaptureStore.Capture(new WarCaptureStore.Key(r.id(),UUID.randomUUID(),x,0),r.attacker(),r.defender(),r.actor(),"HOLD",System.currentTimeMillis(),"CAPTURED");}
 public static void main(String[] args)throws Exception{
  Path path=Files.createTempDirectory("war-terminal-").resolve("raids.db");var errors=new ArrayList<Throwable>();var db=new RaidStore(path,errors::add);done(db.ready());var chunks=new WarCaptureStore(db);long now=System.currentTimeMillis();var one=raid(now);var other=raid(now);done(db.start(one));done(db.start(other));done(chunks.capture(capture(one,0)));done(chunks.capture(capture(other,1)));UUID admin=UUID.randomUUID();
  var ended=done(db.conclude(one.id(),"CANCELLED",admin.toString(),now));check(ended.stream().anyMatch(r->r.id().equals(one.id())&&r.state().equals("CANCELLED")&&r.next()==one.next()),"exact terminal ACK preserves defender cooldown");check(done(chunks.load()).size()==1&&done(chunks.load()).get(0).key().raid().equals(other.id()),"cancel ACK releases only its own war captures");var released=done(chunks.pendingLog()).stream().filter(l->l.action().equals("RELEASED")).toList();check(released.size()==1&&admin.equals(released.get(0).actor()),"durable release records actual administrator");done(db.conclude(one.id(),"CANCELLED",admin.toString(),now+1));check(done(chunks.pendingLog()).stream().filter(l->l.action().equals("RELEASED")).count()==1,"duplicate completion cannot duplicate release receipt");try{db.conclude(one.id(),"SURRENDERED",admin.toString(),now+2);throw new AssertionError("unguarded surrender");}catch(IllegalArgumentException expected){checks++;}denied(db.conclude(UUID.randomUUID(),"CANCELLED",admin.toString(),now));denied(db.conclude(other.id(),"EXPIRED","",now));check(db.healthy()&&errors.isEmpty(),"wrong ID/outcome and premature expiry are validation denials");
  var expiry=done(db.expire(other.ends()));check(expiry.stream().anyMatch(r->r.id().equals(other.id())&&r.state().equals("EXPIRED"))&&done(chunks.load()).isEmpty(),"deadline expiry and release share one ACK");
  var rollback=raid(now);done(db.start(rollback));var held=capture(rollback,2);done(chunks.capture(held));var database=db;done(db.submit(()->{try(var s=database.connection().createStatement()){s.execute("CREATE TRIGGER fail_war_release BEFORE INSERT ON war_chunk_log WHEN NEW.action='RELEASED' BEGIN SELECT RAISE(ABORT,'release fixture failure'); END");}return null;}));denied(db.conclude(rollback.id(),"CANCELLED",admin.toString(),now));check(done(db.raids()).stream().anyMatch(r->r.id().equals(rollback.id())&&r.state().equals("OPEN"))&&done(chunks.load()).size()==1,"failed release rolls back raid state and chunk mutation together");check(!db.healthy()&&errors.size()==1,"actual SQL failure stops further combat authority");done(db.submit(()->{try(var s=database.connection().createStatement()){s.execute("DROP TRIGGER fail_war_release");}return null;}));close(db);
  db=new RaidStore(path,errors::add);done(db.ready());chunks=new WarCaptureStore(db);check(db.healthy()&&done(chunks.load()).size()==1,"restart keeps rolled-back war and capture intact");
  // Reproduce the two-step close written by an old version; startup must finish its release.
  var legacy=db;done(db.submit(()->{try(var p=legacy.connection().prepareStatement("UPDATE raids SET state='CANCELLED' WHERE id=?")){p.setString(1,rollback.id().toString());p.executeUpdate();}return null;}));close(db);db=new RaidStore(path,errors::add);done(db.ready());chunks=new WarCaptureStore(db);check(done(chunks.load()).isEmpty(),"startup repairs cancelled old-version orphan captures");check(done(chunks.pendingLog()).stream().filter(l->l.key().raid().equals(rollback.id())&&l.action().equals("RELEASED")).count()==1,"legacy recovery retains a stable pending admin receipt");
  var previous=raid(System.currentTimeMillis());done(db.start(previous));done(chunks.capture(capture(previous,3)));long later=previous.next()+1;var fresh=new RaidStore.Raid(UUID.randomUUID(),previous.attacker(),previous.defender(),previous.actor(),later,later,later+60000,later+86400000,"OPEN");done(db.start(fresh));check(done(chunks.load()).isEmpty(),"new declaration releases expired predecessor before deleting its row");check(done(chunks.pendingLog()).stream().filter(l->l.key().raid().equals(previous.id())&&l.action().equals("RELEASED")).count()==1,"predecessor cleanup preserves exactly one durable release log");close(db);
  System.out.println("WarConclusionSmoke PASS "+checks+" checks");
 }
}
